{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    dist_map = {}
    for u, v, d in distances:
        key = (min(u, v), max(u, v))
        dist_map[key] = d
    def mutual(u, v):
        return max(core[u], core[v], dist_map[(min(u, v), max(u, v))])
    import heapq
    visited = set()
    mst_edges = []
    total_weight = 0.0
    if not nodes:
        return {'mst_edges': [], 'total_weight': 0.0}
    start = nodes[0]
    visited.add(start)
    heap = []
    for node in nodes[1:]:
        w = mutual(start, node)
        heapq.heappush(heap, (w, start, node))
    while heap and len(visited) < len(nodes):
        w, u, v = heapq.heappop(heap)
        if v in visited:
            continue
        visited.add(v)
        mst_edges.append([u, v, w])
        total_weight += w
        for node in nodes:
            if node not in visited:
                w2 = mutual(v, node)
                heapq.heappush(heap, (w2, v, node))
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"}
